param([switch]$Json)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'status-lib.ps1')
function Get-Auto([string]$Content){$b=([regex]::Matches($Content,[regex]::Escape('<!-- STATUS:AUTO:BEGIN -->'))).Count;$e=([regex]::Matches($Content,[regex]::Escape('<!-- STATUS:AUTO:END -->'))).Count;if($b-ne 1-or$e-ne 1){throw 'marcadores AUTO invalidos'};return ([regex]::Match($Content,'(?s)<!-- STATUS:AUTO:BEGIN -->.*?<!-- STATUS:AUTO:END -->')).Value}
function Field([string]$Block,[string]$Name){$m=[regex]::Match($Block,"(?m)^- $([regex]::Escape($Name)): (.*)$");if(!$m.Success){return $null};$m.Groups[1].Value.Trim()}
try{$root=Invoke-StatusGit @('rev-parse','--show-toplevel');$path=Join-Path $root 'STATUS.md';if(!(Test-Path -LiteralPath $path -PathType Leaf)){throw 'No existe STATUS.md'};$block=Get-Auto (Get-Content -Raw -Encoding UTF8 $path);$actual=Get-StatusSnapshot $root;$errors=@();$warnings=@();$recordedBranch=Field $block 'Rama';$recordedHead=Field $block 'HEAD';$recordedTree=Field $block 'Working tree';if($null -eq $recordedBranch -or $recordedBranch -ne $actual.branch){$errors+='INCONSISTENTE rama no coincide'};if($recordedHead -and $recordedHead -ne $actual.head){$warnings+='STALE HEAD: snapshot regenerable'};if($recordedTree -and $recordedTree -ne $actual.workingTree){$warnings+='STALE working tree: snapshot regenerable'};$recordedVersion=Field $block 'Versión de desarrollo';if($recordedVersion -and $recordedVersion -ne (Format-StatusValue $actual.version.value)){$warnings+='STALE version: snapshot regenerable'};$recordedPr=Field $block 'PR vigente';$expectedPr=if($actual.pullRequest){[string]$actual.pullRequest.number}else{'ninguna PR abierta para este HEAD'};if($recordedPr -and $recordedPr -notmatch [regex]::Escape($expectedPr)){$warnings+='STALE PR: snapshot no refleja la PR vigente'};$recordedCi=Field $block 'CI vigente';if($actual.ci -and $recordedCi -and $recordedCi -notmatch [regex]::Escape([string]$actual.ci.headSha)){$warnings+='STALE CI: corresponde a otro HEAD'};if(!$actual.ci -and $actual.ciAvailable -and $recordedCi -and $recordedCi -notmatch 'NOT RUN'){$warnings+='STALE CI: no hay run aplicable para HEAD'};if(!$actual.githubAvailable){$warnings+='TEMPORAL gh no disponible; PR/CI/release no verificables'};$result=[ordered]@{status=if($errors.Count){'INCONSISTENTE'}elseif($warnings.Count){'STALE'}else{'OK'};errors=$errors;warnings=$warnings;actual=$actual};if($Json){$result|ConvertTo-Json -Depth 20}else{$errors|ForEach-Object{Write-Host "ERROR $_"};$warnings|ForEach-Object{Write-Host "WARNING $_"};if($errors.Count){exit 1};Write-Host 'PASS STATUS.md coherente (warnings regenerables)'};exit 0}catch{Write-Host "ERROR ERROR_REAL $($_.Exception.Message)";if($_.Exception.Message -match 'marcadores AUTO'){exit 1};exit 2}
